import { Dispatch, SetStateAction } from 'react';
import { Box } from '@mui/material';

import { useScreenDimension } from '../../hooks';
import { Typography } from '../atoms';
import { ICONS } from '../../consts';
import { voltaireTheme } from '../../theme';

type Props = {
  filtersOpen?: boolean;
  setFiltersOpen?: Dispatch<SetStateAction<boolean>>;
  chosenFiltersLength?: number;
  chosenSorting: string;
  sortOpen: boolean;
  setSortOpen: Dispatch<SetStateAction<boolean>>;
  children?: React.ReactNode;
  isFiltering?: boolean;
};

/**
 * Renders a chip component for order actions.
 *
 * @component
 * @param {Props} props - The component props.
 * @returns {JSX.Element} - The rendered chip component.
 */
export const OrderActionsChip = (props: Props) => {
  const { isMobile } = useScreenDimension();

  const {
    palette: { secondary },
  } = voltaireTheme;

  const {
    filtersOpen,
    setFiltersOpen = () => {},
    chosenFiltersLength = 0,
    chosenSorting,
    sortOpen,
    setSortOpen,
    isFiltering = true,
    children,
  } = props;

  return (
    <Box
      display="flex"
      width="min-content"
      alignItems="center"
      ml="8px"
      gap={isMobile ? '8px' : '24px'}
      position="relative"
      sx={{ alignSelf: 'end' }}
    >
      {isFiltering && (
        <Box
          sx={{
            position: 'relative',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
            ...(!isMobile && {
              background: filtersOpen ? secondary.main : 'transparent',
              borderRadius: '99px',
              padding: '12px 14px',
            }),
          }}
          onClick={() => {
            setSortOpen(false);
            if (isFiltering) {
              setFiltersOpen(!filtersOpen);
            }
          }}
          data-testid="filters-button"
        >
          <img
            alt="filter"
            src={filtersOpen ? ICONS.filterWhiteIcon : ICONS.filterIcon}
            style={{
              borderRadius: '100%',
              marginRight: '8px',
              overflow: 'visible',
              height: 20,
              width: 20,
              objectFit: 'contain',
              ...(isMobile && {
                background: filtersOpen ? secondary.main : 'transparent',
                padding: '14px',
                marginRight: '0',
              }),
            }}
          />
          {!isMobile && (
            <Typography
              variant="body1"
              sx={{
                color: filtersOpen ? 'white' : 'primaryBlue',
                fontWeight: 500,
              }}
            >
              Filter
            </Typography>
          )}
          {!filtersOpen && chosenFiltersLength > 0 && (
            <Box
              sx={{
                alignItems: 'center',
                background: secondary.main,
                borderRadius: '100%',
                color: 'white',
                display: 'flex',
                fontSize: '12px',
                height: '16px',
                justifyContent: 'center',
                position: 'absolute',
                right: '-3px',
                top: '0',
                width: '16px',
              }}
            >
              <Typography variant="caption" color="#FFFFFF">
                {chosenFiltersLength}
              </Typography>
            </Box>
          )}
        </Box>
      )}
      <Box
        sx={{
          position: 'relative',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          ...(!isMobile && {
            background: sortOpen ? secondary.main : 'transparent',
            borderRadius: '99px',
            padding: '12px 14px',
          }),
        }}
        onClick={() => {
          if (isFiltering) {
            setFiltersOpen(false);
          }
          setSortOpen(!sortOpen);
        }}
        data-testid="sort-button"
      >
        <img
          alt="sort"
          src={sortOpen ? ICONS.sortWhiteIcon : ICONS.sortIcon}
          style={{
            borderRadius: '100%',
            marginRight: '8px',
            height: 20,
            width: 20,
            objectFit: 'contain',
            ...(isMobile && {
              background: sortOpen ? secondary.main : 'transparent',
              padding: '14px',
              marginRight: '0',
            }),
          }}
        />
        {!isMobile && (
          <Typography
            variant="body1"
            sx={{
              color: sortOpen ? 'white' : 'primaryBlue',
              fontWeight: 500,
              whiteSpace: 'nowrap',
            }}
          >
            {chosenSorting ? `Sort by: ${chosenSorting}` : 'Sort'}
          </Typography>
        )}
      </Box>
      {children}
    </Box>
  );
};
